from pathlib import Path
import subprocess,json
r=Path(r'C:\Users\brand\OneDrive\Documents\dead-street')
head=subprocess.check_output(['git','-C',str(r),'rev-parse','HEAD'],text=True).strip()
branch=subprocess.check_output(['git','-C',str(r),'branch','--show-current'],text=True).strip()
index=subprocess.check_output(['git','-C',str(r),'diff','--cached','--name-only'],text=True).strip()
items={'docs/DEAD_STREET_JOURNAL.md':"\n\n## 20260915-selected-range-04 — Owner accepts appearance; group extension proposed\n\nBrandon: \"that is perfect. well done\" accepts the current individual range-circle appearance. He raised concern about too many circles and asked whether ranges should extend to all selected units or specifically weapon-class groupings. This is a design discussion; no group implementation authorized or completed by this entry.\n\nBUILD recommendation (PROPOSED): retain the accepted individual treatment; for a selected weapon-class group show each selected unit's actual equipped range using fainter soft outlines without the interior fill, keeping overlap from accumulating into a bright red patch. Hide ranges for mixed-class groups and Select All. This gives useful class reach information while protecting battlefield readability. Group compositing/performance details remain to be resolved if adopted. Current runtime remains single-selection-only. No new runtime tests needed or run for this discussion. Next: owner chooses the group-display rule. Existing publication block remains separate; appearance acceptance was not treated as explicit GitHub transfer approval. See selected-range-03 for that pending action.\n",'docs/DEAD_STREET_HIVE_MIND.md':"\n\n## 20260915-selected-range-04 — Appearance accepted; group display under discussion\nOWNER-ACCEPTED: current individual range-circle appearance (Brandon: \"that is perfect\"). PROPOSED, not implemented: retain individual fill/rim, add fainter outline-only ranges for weapon-class selections, suppress mixed/Select All ranges and avoid bright overlap buildup. Each unit keeps its actual equipped range. See journal selected-range-04. Next: settle the group rule; current runtime stays individual-only. Publication blocker remains separately recorded in selected-range-03.\n",'docs/DEAD_STREET_PROJECT_CONTROL.md':"\n\n## 20260915-selected-range-04 — Appearance accepted; group display under discussion\nOWNER-ACCEPTED: current individual range-circle appearance (Brandon: \"that is perfect\"). PROPOSED, not implemented: retain individual fill/rim, add fainter outline-only ranges for weapon-class selections, suppress mixed/Select All ranges and avoid bright overlap buildup. Each unit keeps its actual equipped range. See journal selected-range-04. Next: settle the group rule; current runtime stays individual-only. Publication blocker remains separately recorded in selected-range-03.\n",'docs/TACTICAL_CONTROLS_2026-09-13.md':"\n\n## 20260915-selected-range-04 — Appearance accepted; group display under discussion\nOWNER-ACCEPTED: current individual range-circle appearance (Brandon: \"that is perfect\"). PROPOSED, not implemented: retain individual fill/rim, add fainter outline-only ranges for weapon-class selections, suppress mixed/Select All ranges and avoid bright overlap buildup. Each unit keeps its actual equipped range. See journal selected-range-04. Next: settle the group rule; current runtime stays individual-only. Publication blocker remains separately recorded in selected-range-03.\n"}
for name,addition in items.items():
    p=r/name; before=p.read_bytes(); text=before.decode('utf-8')
    if addition.strip() not in text:
        assert p.read_bytes()==before,'Concurrent update: '+name
        p.write_text(text+addition,encoding='utf-8',newline='\n')
    assert addition.strip() in p.read_text(encoding='utf-8')
print(json.dumps({'head':head,'branch':branch,'existing_index_preserved':index,'records_saved':list(items),'runtime_changed':False}))
